// Vanilla JS ArvoCalendarDropdown.
//
// Public Layer 4 floating calendar dropdown. Wraps the internal ArvoCalendar
// grid + CalendarNav header in a portaled dialog surface bound to a
// consumer-provided trigger element. Mirrors the React twin.
//
// Events dispatched on the trigger element:
//   cal-drop:open         -- {} (cancelable; programmatic paths only)
//   cal-drop:close        -- {} (cancelable; programmatic paths only)
//   cal-drop:change       -- { value: Date | null; formattedValue: string }
//   cal-drop:month-change -- { year: number; month: number }

import {
  addMonths,
  applyPositionToSurface,
  buildMemberIndex,
  createOverlaySurface,
  findMemberForDate,
  formatDate,
  getLocaleDateFormat,
  getUserLocale,
  isSameDay,
  parseDate,
  pickAnchorDate,
} from '@arvo/core';
import type {
  MemberIndex,
  OverlaySurface,
  PositionResult,
} from '@arvo/core';
import { ArvoCalendar } from '../Calendar/Calendar';
import type { ArvoCalendarOptions, ArvoCalendarViewMode } from '../Calendar/Calendar';
import { CalendarNav } from '../CalendarNav/CalendarNav';

// Re-export Date helper types? Not needed -- Date is global.

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/**
 * Scoped escape-hatch bag for popover surface options. `width`, `offset`,
 * and `zIndex` flow through; flat options always win on overlap. `zIndex`
 * overrides the overlay hub for this surface only.
 */
export interface CalendarDropdownPopoverProps {
  width?: string;
  offset?: number;
  zIndex?: number;
}

/**
 * Scoped escape-hatch bag for inner ArvoCalendar config the parent does not
 * curate as a flat prop. Pick<ArvoCalendarProps, 'hasOutsideDays' |
 * 'isKeyboardEnabled' | 'size'>. Bag-only keys flow through; flat props
 * always win on overlap.
 */
export type CalendarDropdownCalendarProps = Pick<
  ArvoCalendarOptions,
  'hasOutsideDays' | 'isKeyboardEnabled' | 'size'
>;

export interface MemberItemLike {
  key: string;
  name: string;
  displayName: string;
  index?: number;
}

export interface ArvoCalendarDropdownOptions {
  value?: Date | string | null;
  defaultValue?: Date | string | null;
  format?: string | null;
  locale?: string | null;
  weekStart?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  hasWeeks?: boolean;
  minDate?: Date | string | null;
  maxDate?: Date | string | null;
  frequency?: 'day' | 'week' | 'month' | 'quarter' | 'year' | null;
  memberData?: MemberItemLike[] | null;
  currentMemberIndex?: number | null;
  /** Initial open state for uncontrolled mode. */
  defaultOpen?: boolean;
  isDisabled?: boolean;
  /** Close the dropdown on day-cell select. Default true. */
  isAutoClose?: boolean;
  placement?: 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end' | 'auto';
  /** Accessible name for the dialog panel. Defaults to 'Choose a date'. */
  ariaLabel?: string;
  calendarProps?: CalendarDropdownCalendarProps | null;
  popoverProps?: CalendarDropdownPopoverProps | null;
  onChange?: (payload: { value: Date | null; formattedValue: string }) => void;
  onOpen?: () => boolean | void;
  onClose?: () => boolean | void;
  onOpenChange?: (open: boolean) => void;
  onMonthChange?: (payload: { year: number; month: number }) => void;
  onViewModeChange?: (payload: { mode: ArvoCalendarViewMode }) => void;
}

interface RequiredOptions {
  value: Date | string | null | undefined;
  defaultValue: Date | string | null;
  format: string | null;
  locale: string | null;
  weekStart: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  hasWeeks: boolean;
  minDate: Date | string | null;
  maxDate: Date | string | null;
  frequency: 'day' | 'week' | 'month' | 'quarter' | 'year' | null;
  memberData: MemberItemLike[] | null;
  currentMemberIndex: number | null;
  defaultOpen: boolean;
  isDisabled: boolean;
  isAutoClose: boolean;
  placement: 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end' | 'auto';
  ariaLabel: string;
  calendarProps: CalendarDropdownCalendarProps | null;
  popoverProps: CalendarDropdownPopoverProps | null;
  onChange: ArvoCalendarDropdownOptions['onChange'] | null;
  onOpen: ArvoCalendarDropdownOptions['onOpen'] | null;
  onClose: ArvoCalendarDropdownOptions['onClose'] | null;
  onOpenChange: ArvoCalendarDropdownOptions['onOpenChange'] | null;
  onMonthChange: ArvoCalendarDropdownOptions['onMonthChange'] | null;
  onViewModeChange: ArvoCalendarDropdownOptions['onViewModeChange'] | null;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function sameDay(a: Date | null, b: Date | null): boolean {
  if (a == null && b == null) return true;
  if (a == null || b == null) return false;
  return isSameDay(a, b);
}

function clampToRange(
  v: Date | null,
  min: Date | null,
  max: Date | null,
): Date | null {
  if (v == null) return null;
  if (min && v.getTime() < min.getTime()) return new Date(min.getTime());
  if (max && v.getTime() > max.getTime()) return new Date(max.getTime());
  return v;
}

function coerceDate(v: Date | string | null | undefined, format: string, locale: string): Date | null {
  if (v == null) return null;
  if (v instanceof Date) return Number.isNaN(v.getTime()) ? null : v;
  if (typeof v === 'string') return v.length === 0 ? null : parseDate(v, format, locale);
  return null;
}

function asDate(v: Date | string | null | undefined, format: string, locale: string): Date | null {
  return coerceDate(v, format, locale);
}

let _idCounter = 0;

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export class ArvoCalendarDropdown {
  private _trigger: HTMLElement | null;
  private _opts: RequiredOptions;
  private _id: string;
  private _popoverEl: HTMLDivElement | null = null;
  private _headerEl: HTMLDivElement | null = null;
  private _bodyEl: HTMLDivElement | null = null;
  private _calendar: ArvoCalendar | null = null;
  private _calNav: CalendarNav | null = null;
  private _surface: OverlaySurface | null = null;
  private _committedValue: Date | null = null;
  private _visibleYear: number;
  private _visibleMonth: number;
  private _viewMode: ArvoCalendarViewMode = 'days';
  private _isOpen = false;
  private _destroyed = false;
  private _closingProgrammatically = false;
  private _effLocale: string;
  private _effFormat: string;
  private _memberIndex: MemberIndex | null = null;

  static readonly PLACEMENTS = [
    'top-start',
    'top-end',
    'bottom-start',
    'bottom-end',
    'auto',
  ] as const;

  static readonly DEFAULTS: RequiredOptions = {
    value: undefined,
    defaultValue: null,
    format: null,
    locale: null,
    weekStart: 0,
    hasWeeks: false,
    minDate: null,
    maxDate: null,
    frequency: null,
    memberData: null,
    currentMemberIndex: null,
    defaultOpen: false,
    isDisabled: false,
    isAutoClose: true,
    placement: 'bottom-end',
    ariaLabel: 'Choose a date',
    calendarProps: null,
    popoverProps: null,
    onChange: null,
    onOpen: null,
    onClose: null,
    onOpenChange: null,
    onMonthChange: null,
    onViewModeChange: null,
  };

  static initialize(
    trigger: HTMLElement,
    options?: ArvoCalendarDropdownOptions,
  ): ArvoCalendarDropdown {
    return new ArvoCalendarDropdown(trigger, options);
  }

  constructor(trigger: HTMLElement, options?: ArvoCalendarDropdownOptions) {
    this._trigger = trigger;
    this._id = `arvo-cal-drop-${++_idCounter}`;

    const placement =
      options?.placement &&
      (ArvoCalendarDropdown.PLACEMENTS as readonly string[]).includes(options.placement)
        ? options.placement
        : ArvoCalendarDropdown.DEFAULTS.placement;

    this._opts = {
      ...ArvoCalendarDropdown.DEFAULTS,
      ...options,
      placement,
      value: options?.value,
      defaultValue: options?.defaultValue ?? null,
      calendarProps: options?.calendarProps ?? null,
      popoverProps: options?.popoverProps ?? null,
      onChange: options?.onChange ?? null,
      onOpen: options?.onOpen ?? null,
      onClose: options?.onClose ?? null,
      onOpenChange: options?.onOpenChange ?? null,
      onMonthChange: options?.onMonthChange ?? null,
      onViewModeChange: options?.onViewModeChange ?? null,
    };

    this._effLocale = this._opts.locale ?? getUserLocale();
    this._effFormat = this._opts.format ?? getLocaleDateFormat(this._effLocale);

    const initialRaw =
      this._opts.value !== undefined
        ? this._opts.value
        : this._opts.defaultValue;
    this._committedValue = clampToRange(
      coerceDate(initialRaw, this._effFormat, this._effLocale),
      asDate(this._opts.minDate, this._effFormat, this._effLocale),
      asDate(this._opts.maxDate, this._effFormat, this._effLocale),
    );

    // Visible month/year: anchored to committed value, else today (when in
    // range) -- pickAnchorDate falls back to minDate / maxDate when today is
    // out of range so the dropdown never opens onto a fully-disabled view.
    const anchor = pickAnchorDate(
      this._committedValue,
      asDate(this._opts.minDate, this._effFormat, this._effLocale),
      asDate(this._opts.maxDate, this._effFormat, this._effLocale),
    );
    this._visibleYear = anchor.getFullYear();
    this._visibleMonth = anchor.getMonth();

    this._memberIndex = this._buildMemberIndex();

    this._bindTrigger();

    if (this._opts.defaultOpen && !this._opts.isDisabled) {
      queueMicrotask(() => this.open());
    }
  }

  // -------------------------------------------------------------------------
  // Trigger binding (auto-toggle)
  // -------------------------------------------------------------------------

  private _handleTriggerClick = (e: MouseEvent): void => {
    if (e.defaultPrevented) return;
    this.toggle();
  };

  private _handleTriggerKeyDown = (e: KeyboardEvent): void => {
    if (e.altKey && e.key === 'ArrowDown') {
      e.preventDefault();
      if (!this._isOpen) this.open();
      return;
    }
    if (e.altKey && e.key === 'ArrowUp') {
      e.preventDefault();
      if (this._isOpen) this.close();
      return;
    }
    if (e.key === 'Escape') {
      if (this._isOpen) {
        e.preventDefault();
        this.close();
      }
      return;
    }
  };

  private _bindTrigger(): void {
    if (!this._trigger) return;
    this._trigger.addEventListener('click', this._handleTriggerClick);
    this._trigger.addEventListener('keydown', this._handleTriggerKeyDown);
  }

  private _unbindTrigger(): void {
    if (!this._trigger) return;
    this._trigger.removeEventListener('click', this._handleTriggerClick);
    this._trigger.removeEventListener('keydown', this._handleTriggerKeyDown);
  }

  // -------------------------------------------------------------------------
  // Internals
  // -------------------------------------------------------------------------

  private _buildMemberIndex(): MemberIndex | null {
    if (!this._opts.memberData || !this._opts.frequency) return null;
    try {
      return buildMemberIndex(this._opts.memberData, {
        frequency: this._opts.frequency,
        currentMemberIndex: this._opts.currentMemberIndex,
      });
    } catch {
      return null;
    }
  }

  private _buildPopover(): void {
    if (this._popoverEl) return;

    this._popoverEl = document.createElement('div');
    this._popoverEl.className = this._opts.hasWeeks
      ? 'arvo-cal-drop arvo-cal-drop--show-weeks'
      : 'arvo-cal-drop';
    this._popoverEl.id = this._id;
    this._popoverEl.setAttribute('role', 'dialog');
    this._popoverEl.setAttribute('aria-label', this._opts.ariaLabel);
    this._popoverEl.setAttribute('aria-modal', 'false');
    this._popoverEl.style.position = 'fixed';
    this._popoverEl.style.top = '0';
    this._popoverEl.style.left = '0';
    this._popoverEl.style.margin = '0';
    if (this._opts.popoverProps?.width) {
      this._popoverEl.style.width = this._opts.popoverProps.width;
    }

    this._headerEl = document.createElement('div');
    this._headerEl.className = 'arvo-cal-drop__header';
    this._bodyEl = document.createElement('div');
    this._bodyEl.className = 'arvo-cal-drop__body';
    this._popoverEl.appendChild(this._headerEl);
    this._popoverEl.appendChild(this._bodyEl);

    const minDateResolved = asDate(this._opts.minDate, this._effFormat, this._effLocale);
    const maxDateResolved = asDate(this._opts.maxDate, this._effFormat, this._effLocale);

    this._calNav = CalendarNav.initialize(this._headerEl, {
      visibleYear: this._visibleYear,
      visibleMonth: this._visibleMonth,
      viewMode:
        this._viewMode === 'days' || this._viewMode === 'months' || this._viewMode === 'years'
          ? this._viewMode
          : 'days',
      locale: this._effLocale,
      minDate: minDateResolved,
      maxDate: maxDateResolved,
      isDisabled: this._opts.isDisabled,
      onPrev: () => this._handleHeaderPrev(),
      onNext: () => this._handleHeaderNext(),
      onToday: () => this._handleHeaderToday(),
      onMonthButtonClick: () =>
        this._setViewMode(this._viewMode === 'months' ? 'days' : 'months'),
      onYearButtonClick: () =>
        this._setViewMode(this._viewMode === 'years' ? 'days' : 'years'),
    });

    // Hybrid prop surface: spread calendarProps first; flat / parent-computed
    // values always win on overlap.
    this._calendar = ArvoCalendar.initialize(this._bodyEl, {
      ...(this._opts.calendarProps ?? undefined),
      visibleYear: this._visibleYear,
      visibleMonth: this._visibleMonth,
      viewMode: this._viewMode,
      locale: this._effLocale,
      weekStart: this._opts.weekStart,
      hasWeeks: this._opts.hasWeeks,
      selectedDate: this._committedValue,
      minDate: minDateResolved,
      maxDate: maxDateResolved,
      frequency: this._opts.frequency ?? undefined,
      memberIndex: this._memberIndex,
      currentMemberIndex: this._opts.currentMemberIndex,
    });

    this._bodyEl.addEventListener('cal:select', this._handleCalSelect);
    this._bodyEl.addEventListener('cal:month-change', this._handleCalMonthChange);
    this._bodyEl.addEventListener('cal:viewmode-change', this._handleCalViewModeChange);
    this._bodyEl.addEventListener('cal:dismiss', this._handleCalDismiss);
  }

  private _handleCalSelect = (e: Event): void => {
    const detail = (e as CustomEvent).detail as {
      date?: Date;
      mode: ArvoCalendarViewMode;
    };
    if (!detail || !detail.date) return;
    if (detail.mode === 'days') {
      // Member-aware snapping: when memberIndex is present, snap to keyDate
      // so consumers always receive the bucket's anchor date.
      let next: Date = detail.date;
      if (this._memberIndex) {
        const matched = findMemberForDate(this._memberIndex, detail.date);
        if (matched?.keyDate) next = matched.keyDate;
      }
      this._handleCommit(next);
      if (this._opts.isAutoClose) this.close();
      return;
    }
    // Drill-down: months / years views drill in to days.
    this._visibleYear = detail.date.getFullYear();
    this._visibleMonth = detail.date.getMonth();
    if (detail.mode === 'months') this._setViewMode('days');
    else if (detail.mode === 'years') this._setViewMode('months');
    else this._syncCalendarVisible();
  };

  private _handleCalMonthChange = (e: Event): void => {
    const detail = (e as CustomEvent).detail as { year: number; month: number };
    if (!detail) return;
    this._visibleYear = detail.year;
    this._visibleMonth = detail.month;
    this._syncCalendarVisible();
    this._opts.onMonthChange?.({ year: detail.year, month: detail.month });
    this._dispatch('cal-drop:month-change', { year: detail.year, month: detail.month });
  };

  private _handleCalViewModeChange = (e: Event): void => {
    const detail = (e as CustomEvent).detail as { mode: ArvoCalendarViewMode };
    if (!detail) return;
    this._setViewMode(detail.mode);
  };

  private _handleCalDismiss = (): void => {
    this.close();
  };

  private _setViewMode(mode: ArvoCalendarViewMode): void {
    this._viewMode = mode;
    if (mode === 'days' || mode === 'months' || mode === 'years') {
      // Push the current visible period to the nav BEFORE switching its
      // view mode -- setViewMode rebuilds the nav's left zone and reads
      // its stored visibleYear/visibleMonth when rendering labels, so the
      // nav must see the latest period first or the freshly rebuilt
      // buttons would carry stale labels.
      this._calNav?.setVisibleMonth(this._visibleYear, this._visibleMonth);
      this._calNav?.setViewMode(mode);
    }
    // Push viewMode AND visible period together so the calendar grid never
    // ends up showing the new view-mode against the previous period. Without
    // visibleYear/visibleMonth in this update, a drill-down like
    // "click January in months view" would leave the days view rendering the
    // prior month.
    this._calendar?.update({
      viewMode: mode,
      visibleYear: this._visibleYear,
      visibleMonth: this._visibleMonth,
    });
    this._opts.onViewModeChange?.({ mode });
  }

  private _syncCalendarVisible(): void {
    this._calNav?.setVisibleMonth(this._visibleYear, this._visibleMonth);
    this._calendar?.update({
      visibleYear: this._visibleYear,
      visibleMonth: this._visibleMonth,
    });
  }

  private _handleHeaderPrev(): void {
    if (this._viewMode === 'days') {
      const d = addMonths(new Date(this._visibleYear, this._visibleMonth, 1), -1);
      this._visibleYear = d.getFullYear();
      this._visibleMonth = d.getMonth();
    } else if (this._viewMode === 'months') {
      this._visibleYear -= 1;
    } else if (this._viewMode === 'years') {
      this._visibleYear -= 10;
    }
    this._syncCalendarVisible();
    this._opts.onMonthChange?.({ year: this._visibleYear, month: this._visibleMonth });
    this._dispatch('cal-drop:month-change', {
      year: this._visibleYear,
      month: this._visibleMonth,
    });
  }

  private _handleHeaderNext(): void {
    if (this._viewMode === 'days') {
      const d = addMonths(new Date(this._visibleYear, this._visibleMonth, 1), 1);
      this._visibleYear = d.getFullYear();
      this._visibleMonth = d.getMonth();
    } else if (this._viewMode === 'months') {
      this._visibleYear += 1;
    } else if (this._viewMode === 'years') {
      this._visibleYear += 10;
    }
    this._syncCalendarVisible();
    this._opts.onMonthChange?.({ year: this._visibleYear, month: this._visibleMonth });
    this._dispatch('cal-drop:month-change', {
      year: this._visibleYear,
      month: this._visibleMonth,
    });
  }

  private _handleHeaderToday(): void {
    const today = new Date();
    this._visibleYear = today.getFullYear();
    this._visibleMonth = today.getMonth();
    this._syncCalendarVisible();
    this._opts.onMonthChange?.({ year: this._visibleYear, month: this._visibleMonth });
    this._dispatch('cal-drop:month-change', {
      year: this._visibleYear,
      month: this._visibleMonth,
    });
  }

  private _handleCommit(next: Date | null): boolean {
    const clamped = clampToRange(
      next,
      asDate(this._opts.minDate, this._effFormat, this._effLocale),
      asDate(this._opts.maxDate, this._effFormat, this._effLocale),
    );
    if (sameDay(clamped, this._committedValue)) return false;
    this._committedValue = clamped;
    if (clamped) {
      this._visibleYear = clamped.getFullYear();
      this._visibleMonth = clamped.getMonth();
      this._calNav?.setVisibleMonth(this._visibleYear, this._visibleMonth);
      this._calendar?.update({
        visibleYear: this._visibleYear,
        visibleMonth: this._visibleMonth,
        selectedDate: clamped,
      });
    } else {
      this._calendar?.update({ selectedDate: null });
    }
    const formatted = clamped ? formatDate(clamped, this._effFormat, this._effLocale) : '';
    this._opts.onChange?.({ value: clamped, formattedValue: formatted });
    this._dispatch('cal-drop:change', { value: clamped, formattedValue: formatted });
    return true;
  }

  private _dispatch(name: string, detail: Record<string, unknown> = {}): boolean {
    if (!this._trigger) return true;
    const ev = new CustomEvent(name, { bubbles: true, cancelable: true, detail });
    return this._trigger.dispatchEvent(ev);
  }

  /**
   * Engine-driven close callback. Fires for outside-click and Escape via the
   * hub. Engine-driven dismissals are unconditional and silent -- no
   * cal-drop:close event, no onClose veto. Mirrors the cross-cutting overlay
   * policy.
   */
  private _handleEngineClose = (): void => {
    if (this._closingProgrammatically) return;
    if (!this._isOpen) return;
    this._isOpen = false;
    if (this._trigger) this._trigger.setAttribute('aria-expanded', 'false');
    this._opts.onOpenChange?.(false);
  };

  // -------------------------------------------------------------------------
  // Public API
  // -------------------------------------------------------------------------

  open(): void {
    if (this._destroyed) return;
    if (this._isOpen) return;
    if (this._opts.isDisabled) return;
    if (this._opts.onOpen?.() === false) return;
    if (!this._dispatch('cal-drop:open')) return;

    this._isOpen = true;
    this._buildPopover();

    if (this._popoverEl) this._popoverEl.style.visibility = 'hidden';

    if (!this._surface && this._popoverEl) {
      this._surface = createOverlaySurface({
        id: this._id,
        surface: this._popoverEl,
        type: 'dropdown',
        priority: 20,
        trigger: this._trigger,
        zIndex: this._opts.popoverProps?.zIndex,
        mount: {
          target: document.body,
          removeOnClose: true,
        },
        position: {
          placement: this._opts.placement,
          gap: this._opts.popoverProps?.offset ?? 4,
          apply: (pos: PositionResult, surfaceEl: HTMLElement) => {
            applyPositionToSurface(pos, surfaceEl);
            surfaceEl.style.visibility = '';
          },
        },
        focus: {
          mode: 'trap',
          initialFocus: 'none',
          returnFocus: false,
          getOrderedElements: () => this._getOrderedPopoverElements(),
        },
        transition: 'fade',
        transitionDuration: 150,
        triggerAria: { haspopup: 'dialog' },
        onClose: this._handleEngineClose,
      });
    } else if (this._surface) {
      this._surface.setTrigger(this._trigger);
    }

    void this._surface?.open();

    if (this._trigger) this._trigger.setAttribute('aria-expanded', 'true');

    this._opts.onOpenChange?.(true);

    requestAnimationFrame(() => {
      const target = pickAnchorDate(
        this._committedValue,
        asDate(this._opts.minDate, this._effFormat, this._effLocale),
        asDate(this._opts.maxDate, this._effFormat, this._effLocale),
      );
      this._calendar?.focusCell(target);
    });
  }

  close(): void {
    if (this._destroyed) return;
    if (!this._isOpen) return;
    if (this._opts.onClose?.() === false) return;
    if (!this._dispatch('cal-drop:close')) return;

    this._isOpen = false;
    this._closingProgrammatically = true;
    void this._surface?.close();
    this._closingProgrammatically = false;

    if (this._trigger) {
      this._trigger.setAttribute('aria-expanded', 'false');
      this._trigger.focus({ preventScroll: true });
    }

    this._opts.onOpenChange?.(false);
  }

  toggle(force?: boolean): void {
    const next = force === undefined ? !this._isOpen : force;
    if (next) this.open();
    else this.close();
  }

  isOpen(): boolean {
    return this._isOpen;
  }

  value(): Date | null;
  value(v: Date | string | null): void;
  value(v?: Date | string | null): Date | null | void {
    if (v === undefined) return this._committedValue;
    const coerced = clampToRange(
      coerceDate(v, this._effFormat, this._effLocale),
      asDate(this._opts.minDate, this._effFormat, this._effLocale),
      asDate(this._opts.maxDate, this._effFormat, this._effLocale),
    );
    this._committedValue = coerced;
    if (coerced) {
      this._visibleYear = coerced.getFullYear();
      this._visibleMonth = coerced.getMonth();
    }
    if (this._isOpen) {
      this._calNav?.setVisibleMonth(this._visibleYear, this._visibleMonth);
      this._calendar?.update({
        visibleYear: this._visibleYear,
        visibleMonth: this._visibleMonth,
        selectedDate: coerced,
      });
    }
  }

  formattedValue(): string {
    return this._committedValue
      ? formatDate(this._committedValue, this._effFormat, this._effLocale)
      : '';
  }

  disabled(): boolean;
  disabled(state: boolean): void;
  disabled(state?: boolean): boolean | void {
    if (state === undefined) return this._opts.isDisabled;
    if (this._opts.isDisabled === state) return;
    this._opts.isDisabled = state;
    if (state && this._isOpen) this.close();
  }

  focus(): void {
    if (!this._isOpen) return;
    const target = pickAnchorDate(
      this._committedValue,
      asDate(this._opts.minDate, this._effFormat, this._effLocale),
      asDate(this._opts.maxDate, this._effFormat, this._effLocale),
    );
    this._calendar?.focusCell(target);
  }

  destroy(): void {
    if (this._destroyed) return;
    this._destroyed = true;
    this._unbindTrigger();
    if (this._isOpen) {
      this._isOpen = false;
      void this._surface?.close();
    }
    this._surface?.destroy();
    this._surface = null;
    this._calendar?.destroy();
    this._calendar = null;
    this._calNav?.destroy();
    this._calNav = null;
    this._popoverEl?.remove();
    this._popoverEl = null;
    this._headerEl = null;
    this._bodyEl = null;
    if (this._trigger) {
      this._trigger.removeAttribute('aria-haspopup');
      this._trigger.removeAttribute('aria-controls');
      this._trigger.removeAttribute('aria-expanded');
    }
    this._trigger = null;
  }

  /**
   * Tab cycle inside the popover. Mirrors the React `getOrderedElements`
   * contract: calendar cell -> prev / month / year / next / today.
   */
  private _getOrderedPopoverElements(): Array<HTMLElement | null> {
    const root = this._popoverEl;
    if (!root) return [];
    const cell = root.querySelector<HTMLElement>('.arvo-cal__cell[tabindex="0"]');
    const prev = root.querySelector<HTMLElement>('.arvo-cal-nav__prev');
    const month = root.querySelector<HTMLElement>('.arvo-cal-nav__month-btn');
    const year = root.querySelector<HTMLElement>('.arvo-cal-nav__year-btn');
    const next = root.querySelector<HTMLElement>('.arvo-cal-nav__next');
    const today = root.querySelector<HTMLElement>('.arvo-cal-nav__today');
    return [cell, prev, month, year, next, today];
  }
}
